namespace Invoicing;

/// <summary>Resolves the VAT due for a net amount given account and jurisdiction.</summary>
public sealed class VatResolver
{
    public decimal Resolve(Account account, decimal net, string countryCode)
    {
        ArgumentNullException.ThrowIfNull(account);

        if (net <= 0m)
            return 0m;

        var rate = GetBaseRate(countryCode);
        rate = ApplyAccountRules(rate, account.Kind, net);
        rate = ApplyHighValueCap(rate, net);
        return net * rate;
    }

    private static decimal GetBaseRate(string countryCode) => countryCode switch
    {
        "GB" => 0.20m,
        "DE" => 0.19m,
        "FR" => 0.20m,
        "IE" => 0.23m,
        _ => 0m
    };

    private static decimal ApplyAccountRules(decimal rate, AccountKind kind, decimal net) =>
        kind switch
        {
            AccountKind.Government => 0m,
            AccountKind.Business when net > 10_000m => rate * 0.5m,
            _ => rate
        };

    private static decimal ApplyHighValueCap(decimal rate, decimal net) =>
        rate > 0m && net > 100_000m ? Math.Min(rate, 0.15m) : rate;
}
